/*
  =============================================================================
  BOLT PLATFORM - SEED DATA: BBM bootstrap + app screens
  =============================================================================

  Purpose:
    - Ensure service `bbm`, product `za-bbm`, and default English locale exist
    - Seed bbm service-level app screens, sections, and labels from live DEV

  Notes:
    - Login, assets, translations, page behaviour, and menu are seeds 11–15.
  =============================================================================
*/

DO $$
DECLARE
  v_service uuid;
  v_product uuid;
BEGIN
  SELECT id INTO v_service FROM backoffice.services WHERE slug = 'bbm';
  IF v_service IS NULL THEN
    INSERT INTO backoffice.services (id, slug, display_name, description, status)
    VALUES ('a1b2c3d4-e5f6-4789-a012-3456789abcde'::uuid, 'bbm', 'Big Brother', 'Big Brother (Bravigo family)', 'active')
    RETURNING id INTO v_service;
  ELSE
    UPDATE backoffice.services
    SET display_name = 'Big Brother',
        description = 'Big Brother (Bravigo family)',
        status = 'active',
        updated_at = now()
    WHERE id = v_service;
  END IF;

  SELECT id INTO v_product FROM backoffice.products WHERE service_id = v_service AND slug = 'za-bbm';
  IF v_product IS NULL THEN
    INSERT INTO backoffice.products (
      id, service_id, slug, display_name, country_code, is_global,
      native_bundle_id, status, hostname_staging, hostname_production, is_default, timezone
    )
    VALUES (
      'b2c3d4e5-f6a7-4890-b123-456789abcdef'::uuid, v_service, 'za-bbm', 'BBM ZA', 'ZA', false,
      NULL, 'active', NULL, NULL, true, NULL
    )
    RETURNING id INTO v_product;
  ELSE
    UPDATE backoffice.products
    SET display_name = 'BBM ZA',
        country_code = 'ZA',
        is_default = true,
        updated_at = now()
    WHERE id = v_product;
  END IF;

  INSERT INTO backoffice.product_locales (id, product_id, language_code, display_name, is_default, status)
  VALUES ('c3d4e5f6-a7b8-4901-c234-56789abcdef0'::uuid, v_product, 'en', 'English', true, 'active')
  ON CONFLICT (product_id, language_code) DO UPDATE SET
    display_name = EXCLUDED.display_name,
    is_default = EXCLUDED.is_default,
    status = EXCLUDED.status;

